Mesh<Point, double> mesh;
std::unordered_map<RT::Cell_handle, std::vector<Point>> cell_to_vertices;

// First collect all vertices from the triangulation
for (RT::Finite_cells_iterator it = rt.finite_cells_begin();
     it != rt.finite_cells_end(); ++it) {
    RT::Cell_handle c = *it;
    for (unsigned i = 0; i < 4; ++i) {
        Point p = rt.point(c->vertex(i));
        cell_to_vertices[c].push_back(p);
    }
}

// Process each edge to find incident cells
for (RT::Edge_iterator eit = rt.edges_begin();
     eit != rt.edges_end(); ++eit) {
    RT::Edge e = *eit;
    if (is_small_edge(rt, e, threshold)) {
        continue;
    }

    // Get the two incident cells
    RT::Cell_handle c1 = e.first->neighbor(e.second);
    RT::Cell_handle c2 = e.first;

    // Skip if either cell is infinite
    if (c1 == rt.infinite_cell() || c2 == rt.infinite_cell()) {
        continue;
    }

    // Find the common edge vertices
    unsigned i1 = e.first->vertex_index(e.second);
    unsigned i2 = e.first->vertex_index(e.second ^ 1);

    // Get the vertices for both cells
    std::vector<Point> vertices1 = cell_to_vertices[c1];
    std::vector<Point> vertices2 = cell_to_vertices[c2];

    // Create a polygon for the face
    std::vector<Point> face_vertices;
    face_vertices.push_back(vertices1[i1]);
    face_vertices.push_back(vertices1[i2]);

    // Add the other vertices from c1 in order
    for (unsigned i = 0; i < 4; ++i) {
        if (i != i1 && i != i2) {
            face_vertices.push_back(vertices1[i]);
        }
    }

    // Add the other vertices from c2 in reverse order
    for (int i = 3; i >= 0; --i) {
        if (i != i1 && i != i2) {
            face_vertices.push_back(vertices2[i]);
        }
    }

    // Add the face to the mesh
    mesh.add_face(face_vertices);
}

// Add edge lengths as vertex attributes
for (RT::Edge_iterator eit = rt.edges_begin();
     eit != rt.edges_end(); ++eit) {
    RT::Edge e = *eit;
    if (is_small_edge(rt, e, threshold)) {
        continue;
    }

    double length = std::sqrt(rt.segment(e).squared_length());
    unsigned i1 = e.first->vertex_index(e.second);
    unsigned i2 = e.first->vertex_index(e.second ^ 1);

    // Set edge length as attribute for both vertices
    mesh.set_vertex_attribute(i1, length);
    mesh.set_vertex_attribute(i2, length);
}

return mesh;

